def unit_of_work(metadata=None, timeout=None):
    def decorator(function):
        def wrapper(tx):
            try:
                function(tx)
            except Exception as e:
                tx.rollback()
                raise e
        if metadata is not None and timeout is not None:
            return tx.mark_entity(metadata).timeout(timeout).do(wrapper)
        elif metadata is not None:
            return tx.mark_entity(metadata).do(wrapper)
        elif timeout is not None:
            return tx.timeout(timeout).do(wrapper)
        else:
            return tx.do(wrapper)
    return decorator

def unit_of_work(metadata=None, timeout=None):
    # Check if the input parameters are valid.
    if timeout is not None and timeout < 0:
        raise ValueError("Timeout must be a non-negative value")

    # Define a new transaction function wrapper.
    def wrapper(func):
        # Wrap the original function with a new function.
        def new_func(tx):
            # Set the transaction metadata if specified.
            if metadata is not None:
                for key, value in metadata.items():
                    tx.setMeta(key, value)

            # Set the transaction timeout if specified.
            if timeout is not None:
                tx.timeout = timeout

            # Execute the wrapped function.
            return func(tx)

        # Add the transaction decorator.
        @wraps(func)
        def decorated_func(tx):
            # Execute the wrapped function and catch any errors.
            try:
                return new_func(tx)
            except Exception as e:
                # If an exception occurs, rollback the transaction and reraise the exception.
                tx.rollback()
                raise e

        return decorated_func

    return wrapper

