def unit_of_work(metadata=None, timeout=None):
    """
    Decorate a transaction function to apply extra control over how the transaction is carried out. A timeout may be applied.

    :param metadata: a dictionary with metadata
    :type metadata: dict
    :param timeout: the transaction timeout in seconds
    :type timeout: float or None
    """

    def _unit_of_work(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # If metadata is specified, attach it to the transaction using the Neo4j procedure
            if metadata:
                neo4j.set_tx_metadata(metadata)

            # If a timeout is specified, set it on the transaction using the Neo4j procedure
            if timeout is not None:
                try:
                    neo4j.set_tx_timeout(timeout)
                except ValueError:
                    # If the timeout is negative, log an error and use the default timeout
                    logger.error("Invalid transaction timeout. Using default timeout instead.")
            else:
                # Otherwise, use the default timeout configured in the database
                neo4j.set_tx_timeout()

            # Execute the transaction function and return its result
            return func(*args, **kwargs)

        return wrapper

    return _unit_of_work

