def round_half_to_even(n):
    """
    Returns the integer that is closest to n, but rounded to the nearest even number.
    If n is halfway between two integers, it is rounded down towards the even number.

    :param n: the number to be rounded
    :return: the rounded number
    """

    if n == 0 or n == 1:
        return int(n)

    rounded = int(n + 1) // 2 * 2

    if rounded >= n:
        return rounded
    else:
        return rounded + 2

