def extostr(cls, e, max_level=30, max_path_level=5):
    result = ""
    try:
        result = str(e)
        if not result:
            result = "Exception with no message"
        if e.args:
            result += ": " + str(e.args[0]).strip()
        if hasattr(e, "__traceback__") and e.__traceback__:
            tb = e.__traceback__
            tb_lines = []
            while tb is not None:
                if len(tb_lines) == max_level:
                    break
                tb_lines.append("  " * (len(tb_lines) + 1) + " at " + str(tb.tb_frame.f_code).lstrip("<>") + " in " + str(tb.tb_frame.f_code.co_filename).strip() + " (line " + str(tb.tb_lineno) + ")")
                tb = tb.tb_next
            if tb_lines:
                result += "\n" + "\n".join(tb_lines)
        if hasattr(e, "__cause__") and e.__cause__:
            result += "\nCaused by: " + extostr(e.__cause__, max_level - 1, max_path_level)
    except (TypeError, IndexError, RuntimeError):
        result = "Error formatting exception"
    if len(result) > max_path_level:
        result = result[:max_path_level] + "..."
    return result

