    def get_suffix(elements, start_index):
        suffix = []
        for i in range(start_index, len(elements)):
            suffix.append(elements[i])
        return suffix

    def merge_suffixes(suffix1, suffix2):
        merged_suffix = []
        for element in suffix1:
            if element in suffix2:
                merged_suffix.append(element)
            else:
                merged_suffix.extend(suffix2)
                break

        return merged_suffix

    merged_ordering = []

    for ordering in orderings:
