            continue
        elif len(ordering) == 1:
            merged_ordering.append(ordering[0])
        else:
            start_index = 0
            for i in range(1, len(ordering)):
                suffix = get_suffix(ordering, start_index)
                if suffix[0] == ordering[i]:
                    start_index = i
                else:
                    merged_suffix = merge_suffixes(suffix, get_suffix(ordering, i))
                    merged_ordering.extend(merged_suffix)
                    start_index = i

