import krake.data.kubernetes as kube

def generate_default_observer_schema(app: kube.Application):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the manifest for the application
    manifest = app.manifest

    # Initialize an empty dictionary to store the default observer schemas
    default_observer_schemas = {}

    # Iterate over the resources in the manifest
    for resource in manifest.resources:
        # If a custom observer schema is not defined, generate a default schema
        if not resource.observer_schema:
            default_observer_schemas[resource.name] = generate_default_observer_schema_for_resource(resource)

    return default_observer_schemas

def generate_default_observer_schema_for_resource(resource: kube.Resource):
    """Generate a default observer schema for a Kubernetes resource.

    Args:
        resource (krake.data.kubernetes.Resource): The Kubernetes resource for which to
            generate a default observer schema
    """
    # If the resource is a Deployment, generate a default schema for the replicas field
    if resource.kind == kube.ResourceKind.Deployment:
        return {
            'replicas': {
                'type': 'integer'
            }
        }
    # If the resource is a StatefulSet, generate a default schema for the replicas field
    elif resource.kind == kube.ResourceKind.StatefulSet:
        return {
            'replicas': {
                'type': 'integer'
            }
        }
    # If the resource is a Ingress, generate a default schema for the rules field
    elif resource.kind == kube.ResourceKind.Ingress:
        return {
            'rules': {
                'type': 'array',
                'items': {
                    'type': 'object',
                    'properties': {
                        'host': {
                            'type': 'string'
                        },
                        'http': {
                            'type': 'object',
                            'properties': {
                                'paths': {
                                    'type': 'array',
                                    'items': {
                                        'type': 'object',
                                        'properties': {
                                            'backend': {
                                                'type': 'object',
                                                'properties': {
                                                    'serviceName': {
                                                        'type': 'string'
                                                    },
                                                    'servicePort': {
                                                        'type': 'integer'
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    # If the resource is a Job, generate a default schema for the completions field
    elif resource.kind == kube.ResourceKind.Job:
        return {
            'completions': {
                'type': 'integer'
            }
        }
    # If the resource is a CronJob, generate a default schema for the schedule field
    elif resource.kind == kube.ResourceKind.CronJob:
        return {
            'schedule': {
                'type': 'string'
            }
        }
    # If the resource is a DaemonSet, generate a default schema for the updateStrategy field
    elif resource.kind == kube.ResourceKind.DaemonSet:
        return {
            'updateStrategy': {
                'type': 'object',
                'properties': {
                    'rollingUpdate': {
                        'type': 'object',
                        'properties': {
                            'maxUnavailable': {
                                'type': 'string'
                            }
                        }
                    }
                }
            }
        }
    # By default, generate a catch-all schema with a `type` property set to `object`
    else:
        return {
            'type': 'object'
        }

def generate_default_observer_schema(app):
    observer_schema = {}
    for resource_manifest in app.spec.manifest:
        # Add default schema for Kubernetes resources in `app.spec.manifest` having custom observers
        if isinstance(resource_manifest, kubernetes.CustomResourceManifest):
            for resource in resource_manifest.resources:
                # Check if `resource` has a custom observer specified
                if not resource.custom_observer:
                    # Generate a default observer schema for `resource`
                    default_observer = generate_default_observer(resource_manifest, resource)
                    observer_schema[resource.name] = default_observer
    return observer_schema

def generate_default_observer(resource_manifest, resource):
    # Generate a default observer schema for `resource`
    # based on the `resource_manifest` metadata
    default_observer = {}
    for metadata_field in resource_manifest.metadata:
        # Add fields from `resource_manifest.metadata` to the default observer
        if metadata_field in resource.metadata:
            default_observer[metadata_field] = resource.metadata[metadata_field]
    # Add required fields for all Kubernetes resources
    default_observer["tag"] = resource.tag
    default_observer["workloads"] = resource.workloads
    default_observer["ignore-fields"] = resource.ignore_fields
    return default_observer

def generate_default_observer_schema(app):
    # Check if the app already has a custom observer schema
    if app.observer_schema:
        return app.observer_schema

    # Generate the default observer schema for each Kubernetes resource present in the app's manifest
    manifest_resources = {
        resource.kind: {
            resource.api_version: {
                resource.name: {
                    "kind": resource.kind,
                    "api_version": resource.api_version,
                    "name": resource.name,
                    "fields": []
                }
            }
        }
    }

    for resource in app.spec.manifest.resources:
        if resource.kind not in manifest_resources:
            manifest_resources[resource.kind] = {resource.api_version: {resource.name: {"kind": resource.kind, "api_version": resource.api_version, "name": resource.name, "fields": []}}}
        elif resource.api_version not in manifest_resources[resource.kind]:
            manifest_resources[resource.kind][resource.api_version] = {resource.name: {"kind": resource.kind, "api_version": resource.api_version, "name": resource.name, "fields": []}}
        else:
            manifest_resources[resource.kind][resource.api_version][resource.name] = {"kind": resource.kind, "api_version": resource.api_version, "name": resource.name, "fields": []}

    for kind, api_version_dict in manifest_resources.items():
        for api_version, name_dict in api_version_dict.items():
            for name, field_dict in name_dict.items():
                field_dict["fields"] = get_default_observer_schema_fields(kind, api_version, name)

    return manifest_resources

def get_default_observer_schema_fields(kind, api_version, name):
    # If the kind is a deployment, generate fields for the common deployment spec attributes
    if kind == "Deployment":
        return [
            {"name": "spec", "type": "object", "properties": {
                "replicas": {"type": "integer"},
                "strategy": {"type": "object", "properties": {"type": "string"}}
                }}
        ]
    return []

def convert_out_style(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        template = Template(sql)
    except ValueError as e:
        raise InvalidInputError("Invalid SQL query") from e
    try:
        if isinstance(params, Mapping):
            # Ordinal parameters style
            out_style_params = []
            for i, param in params.items():
                out_style_params.append(("${{{}}}" if isinstance(i, str) else "{}").format(i))
                template.kwargs[i] = param
        else:
            # Named parameters style
            out_style_params = {}
            for i, param in enumerate(params):
                out_style_params[f"$_{i}"] = param
                template.kwargs[f"${i}"] = param
        template.substitute()
        return template.template, out_style_params
    except TypeError as e:
        raise InvalidInputError("Invalid parameter type") from e

def format(sql, params):
	"""Convert the SQL query to use the out-style parameters instead of the in-style parameters."""
	formatted_sql, out_style_params = "", []

	if isinstance(params, dict):
		# Named parameter style
		for param, value in params.items():
			formatted_sql += ":{} = {} ".format(param, value)
			out_style_params.append((param, value))
	else:
		# Ordinal parameter style
		for i, value in enumerate(params):
			formatted_sql += "{} ".format(value)
			out_style_params.append((i + 1, value))

	return formatted_sql, out_style_params

class SQLParams:
    def __init__(self, in_style):
        self.in_style = in_style

    def format(
        self,
        sql,
        params
    ):
        if self.in_style == "namestyle":
            if not isinstance(params, collections.abc.Mapping):
                raise ValueError("Incorrect type for params, expected Mapping")
            formatted_params = {}
            for key, value in params.items():
                formatted_params[key] = value
            return (sql, formatted_params)
        elif self.in_style == "ordinalstyle":
            if not isinstance(params, collections.abc.Sequence):
                raise ValueError("Incorrect type for params, expected Sequence")
            formatted_params = []
            for value in params:
                formatted_params.append(value)
            return (sql, formatted_params)
        else:
            raise ValueError(f"Unsupported in_style: {self.in_style}")

def formatmany(sql, many_params):
    out_params = []

    for params in many_params:
        out_params.append({})
        pos = 1
        for key, value in params.items():
            out_params[-1][f":{key}"] = value
            sql = sql.replace(f"{key}", f":{key}")
            pos += 1

    return sql, out_params

def formatmany(sql, many_params):
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(many_params, Iterable):
        raise TypeError("many_params must be an Iterable")
    if not all(isinstance(x, (Mapping, Sequence)) for x in many_params):
        raise TypeError("many_params must contain only Mappings or Sequences")

    formatted_sql = sql
    out_style_params = []
    for params in many_params:
        if isinstance(params, Mapping):
            if not all(isinstance(k, (str, int)) and isinstance(v, Any) for k, v in params.items()):
                raise TypeError("params must be a Mapping[Union[str, int], Any]")
            out_style_params.append(dict(params))
        elif isinstance(params, Sequence):
            if not all(isinstance(v, Any) for v in params):
                raise TypeError("params must be a Sequence[Any]")
            out_style_params.append(list(params))
        else:
            raise TypeError("many_params must contain only Mappings or Sequences")

    return formatted_sql, out_style_params

def formatmany(self, sql, many_params):
	formatted_sql = []
	params = []

	for param in many_params:
		if isinstance(param, Mapping):
			params.append(tuple(param.items()))
		else:
			params.append(tuple(param))

	for index, param in enumerate(params):
		formatted_sql.append(sql)
		for key, value in param:
			formatted_sql[index] = formatted_sql[index].replace(f":{key}", value)

	return "".join(formatted_sql), params

def validate(self, path):
    """
    :type path: str
    :rtype: bool
    """
    # Validate OCFL object at path or pyfs root
    # Returns True if valid (warnings permitted), False otherwise.
    validate_input_path(path)
    try:
        doc_path = path + ".file"
        if os.path.exists(doc_path):
            with open(doc_path, "rt") as f:
                validate_object_doc(f)
        else:
            # If the object documentation does not exist, assume it is a valid object
            return True
        bag_path = path + "/bags"
        if not os.path.exists(bag_path):
            # Object must have a "bags" directory
            return False
        for bag in os.listdir(bag_path):
            validate_bag(bag_path + "/" + bag)
        return True
    except Exception as e:
        return False

def validate_input_path(path):
    if not isinstance(path, str):
        raise ValueError("path must be a str")
    if not os.path.normpath(path):
        raise ValueError("path must be a valid file path")

def validate_object_doc(f):
    for line in f:
        if line.startswith("###"):
            continue
        if line.strip().lower().startswith("id:"):
            # ID must be unique and valid
            if not validate_id(line.strip()[3:]):
                return False
        if line.strip().lower().startswith("title:"):
            # Title must be a valid string
            if not validate_string(line.strip()[6:]):
                return False
        if line.strip().lower().startswith("ocfl-version:"):
            # OCFL version must be a valid version string
            if not validate_version_string(line.strip()[14:]):
                return False
        if line.strip().lower().startswith("root-revision:"):
            # Root revision must be a valid SHA-1 digest
            if not validate_digest(line.strip()[14:]):
                return False
        if line.strip().lower().startswith("head-revision:"):
            # Head revision must be a valid SHA-1 digest
            if not validate_digest(line.strip()[13:]):
                return False
        if line.strip().lower().startswith("head-sequence-number:"):
            # Head sequence number must be a valid integer
            if not validate_integer(line.strip()[21:]):
                return False
    return True

def validate_bag(bag_path):
    # For each file in the bag, check that it is a valid file
    for file in os.listdir(bag_path):
        if not validate_file(bag_path + "/" + file):
            return False
    # For each subdirectory in the bag, check that it is a valid bag
    for dir in os.listdir(bag_path):
        if not validate_bag(bag_path + "/" + dir):
            return False
    return True

def validate_file(file_path):
    # File path must be a valid file path
    if not os.path.ismount(file_path):
        return False
    # File must have a valid digest in the tag manifest
    return validate_tag_manifest(file_path)

def validate_tag_manifest(file_path):
    # File path must have a corresponding tag manifest
    if not file_path + ".tagmanifest" == os.path.exists(file_path):
        return False
    # Tag manifest must be a valid JSON object
    with open(file_path + ".tagmanifest", "rt") as f:
        data = json.load(f)
        if not isinstance(data, dict):
            return False
        # Digest for the file must be included in the tag manifest
        if "sha1" not in data.get("tags", {}):
            return False
        return True

def validate_id(id):
    # ID must be a valid string
    if not isinstance(id, str):
        return False
    # ID must not contain invalid characters
    for c in id:
        if c not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-":
            return False
    # ID must start with a letter
    if not id[0].isalpha():
        return False
    # ID must not start with "ocfl_root" or "archival_object"
    if id.startswith("ocfl_root") or id.startswith("archival_object"):
        return False
    return True

def validate_string(string):
    # String must be a valid string
    if not isinstance(string, str):
        return False
    # String must not contain invalid characters
    for c in string:
        if c not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-":
            return False
    return True

def validate_version_string(version):
    # Version must be a valid string
    if not isinstance(version, str):
        return False
    # Version must match the format "X.Y.Z"
    parts = version.split(".")
    if len(parts) != 3:
        return False
    for part in parts:
        if not part.isdigit():
            return False
    return True

def validate_digest(digest):
    # Digest must be a valid string
    if not isinstance(digest, str):
        return False
    # Digest must be a valid SHA-1 digest in hexadecimal format
    return validate_sha1_digest(digest)

def validate_sha1_digest(digest):
    # Digest must be a valid SHA-1 digest in hexadecimal format
    if len(digest) != 40:
        return False
    try:
        int(digest, 16)
    except ValueError:
        return False
    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a valid directory
    if not os.path.isdir(path):
        raise InvalidOcflPathError("Path is not a directory: {}".format(path))

    # Check if the object root contains an OCFL manifest
    manifest_path = os.path.join(path, "ocfl_root", "ocfl_object", "ocfl_metadata", "ocfl_object.json")
    if not os.path.isfile(manifest_path):
        raise InvalidOcflObjectError("OCFL manifest not found at: {}".format(manifest_path))

    # Check if the object has a valid OCFL identifier
    try:
        with open(manifest_path, "r") as f:
            manifest = json.load(f)
            fsid = manifest["ocfl_object"]["id"]
            if not Fsid.is_valid(fsid):
                raise InvalidFsidError("Invalid FSID: {}".format(fsid))
    except (FileNotFoundError, json.JSONDecodeError):
        raise InvalidOcflManifestError("Failed to read or parse OCFL manifest: {}".format(manifest_path))

    # Check if the object root contains a valid inventory
    inventory_path = os.path.join(path, "ocfl_root", "ocfl_inventory.json")
    if not os.path.isfile(inventory_path):
        raise InvalidOcflInventoryError("OCFL inventory not found at: {}".format(inventory_path))

    # Check if the inventory is valid
    try:
        with open(inventory_path, "r") as f:
            inventory = json.load(f)
            for obj in inventory["ocfl_objects"]:
                if obj["fsid"] != fsid:
                    raise InvalidOcflInventoryError("Invalid OCFL inventory: {}".format(inventory_path))
    except (FileNotFoundError, json.JSONDecodeError):
        raise InvalidOcflInventoryError("Failed to read or parse OCFL inventory: {}".format(inventory_path))

    # Check if the object has a valid FSID
    if not Fsid.is_valid(fsid):
        raise InvalidFsidError("Invalid FSID: {}".format(fsid))

    # Check if the object has a valid parent FSID
    if manifest["ocfl_object"].get("parent", None) and not Fsid.is_valid(manifest["ocfl_object"]["parent"]):
        raise InvalidFsidError("Invalid parent FSID: {}".format(manifest["ocfl_object"]["parent"]))

    # Check if the object has a valid root directory
    if os.path.join(path, "ocfl_root") != os.path.realpath(path):
        raise InvalidOcflRootError("Invalid OCFL root directory: {}".format(path))

    return True

def validate(self, path):
    try:
        # Check if path is valid
        if not path.startswith('/'):
            raise ValueError('Path must be absolute')
        if not os.path.isdir(path):
            raise ValueError('Path must be a directory')

        # Check for valid OCFL object structure
