            raise ValueError('Missing content directory')
        if not os.path.isfile(os.path.join(path, 'description.n3')):
            raise ValueError('Missing description.n3 file')

        # Check for valid OCFL data structures
        description = etree.parse(os.path.join(path, 'description.n3'))
        root = description.getroot()
        if root.tag != '{http://www.openarchives.org/ocfl/1.0/ns/}object':
            raise ValueError('Invalid root element')
        if not root.find('{http://www.openarchives.org/ocfl/1.0/ns/}id'):
            raise ValueError('Missing object ID')
        if not root.find('{http://www.openarchives.org/ocfl/1.0/ns/}type'):
            raise ValueError('Missing object type')
        if not root.find('{http://www.openarchives.org/ocfl/1.0/ns/}lastModified'):
            raise ValueError('Missing last modified date')

        # Check for valid ACL if present
        acl = os.path.join(path, 'acl.n3')
        if os.path.isfile(acl):
            acl_description = etree.parse(acl)
            acl_root = acl_description.getroot()
            if acl_root.tag != '{http://www.w3.org/ns/auth/acl#}acl':
                raise ValueError('Invalid ACL root element')

        return True
    except (FileNotFoundError, ValueError, etree.XMLSyntaxError) as e:
        print(f'Invalid OCFL object: {e}')
        return False

