def check_digests_present_and_used(manifest_files, digests_used):
    """Check that all necessary digests are present and used in the given manifest files."""

    # Check that all required digests are present in the manifest files
    for digest in digests_used:
        is_present = False
        for manifest in manifest_files:
            with open(manifest, 'r') as f:
                content = f.read()
                if re.search(fr"^{digest}: *\w+ *$", content, re.MULTILINE):
                    is_present = True
                    break
        if not is_present:
            raise ValueError(f"Required digest '{digest}' is not present in the manifest files.")

    # Check that all digests used in the manifest files are actually used in the code
    for manifest in manifest_files:
        with open(manifest, 'r') as f:
            content = f.read()
            # Match all digest references in the manifest, ignoring case and spaces
            digests_in_manifest = re.findall(r"^{([\w\-]+): *\w+ *$", content, re.MULTILINE)
            for digest in digests_in_manifest:
                if digest not in digests_used:
                    raise ValueError(f"Digest '{digest}' in the manifest file '{manifest}' is not used in the code.")

    # Check that all digests used in the code are present in the manifest files
    for digest in digests_used:
