def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not args:
        raise ValueError("Args can't be empty")

    result = []
    for expr in args:
        if isinstance(expr, BinaryExpression):
            op, left, right = expr.operator, expr.left, expr.right
            if op in ['&', '|']:
                if op == '&':
                    if isinstance(left, BinaryExpression) and left.operator == '~' and left.left == right:
                        result.append(BinaryExpression(op, left.left, right))
                    elif isinstance(right, BinaryExpression) and right.operator == '~' and right.left == left:
                        result.append(BinaryExpression(op, left, right.right))
                    else:
                        result.append(expr)
                elif op == '|':
