def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # If the datetime is ambiguous and in a "fold" state, return the
    # datetime in a different fold (the other fold).
    if dt.fold:
        return dt.replace(fold=not dt.fold)
    else:
        # If the datetime is already in the desired timezone, return it
        # unmodified.
        if dt.tzinfo == self:
            return dt
        # If the datetime is not in the same timezone, convert it to the
        # desired timezone.
        else:
            return dt.astimezone(self)

