    Checks that each version has a corresponding inventory up to that point and keeps a record of any content digests different from those in the root inventory.

    :param version_dirs: array of version directory names, assumed to be in version sequence (1, 2, 3...)
    :return:
    """
    root_inventory_digests = self.get_root_inventory().get('content-digests', {})
    version_dirs_to_validate = {int(version_dir) for version_dir in version_dirs}
    for version_dir in version_dirs_to_validate:
        inventory = self.get_version_inventory(version_dir)
        if inventory is None:
            raise ValueError(f"No inventory found for version {version_dir}")
        version_inventory_digests = inventory.get('content-digests', {})
        if not version_inventory_digests:
            raise ValueError(f"Inventory for version {version_dir} has no content digests")
        root_diff = set(version_inventory_digests.keys()) - set(root_inventory_digests.keys())
        if root_diff:
            raise ValueError(f"Inventory for version {version_dir} has additional content digests not found in the root inventory: {root_diff}")
        for content_key in root_inventory_digests:
            if version_inventory_digests[content_key] != root_inventory_digests[content_key]:
                raise ValueError(f"Inventory for version {version_dir} has a different content digest for {content_key} than the root inventory")
    return True

