def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    global_namespace = argparse.Namespace()
    subparser_namespaces = {}

    for unparsed_argument in unparsed_arguments:
        # Handle global args
        if unparsed_argument.startswith("-"):
            global_namespace.add(unparsed_argument)
        else:
            # Handle subparser args
            subparser_name = unparsed_argument
            subparser_namespace = argparse.Namespace()
            subparser_namespaces[subparser_name] = subparser_namespace

    return {
        "global": global_namespace,
        **subparser_namespaces
    }

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    # Iterate over the unparsed arguments and try to give each subparser a shot at parsing them
    for argument in unparsed_arguments:
        for name, parser in subparsers.items():
            # Try to parse the argument with the given subparser
            try:
                namespace = parser.parse_known_args(argument.split())[0]
            except ArgumentError:
                # The argument was not recognized by the subparser, so we move on to the next one
                continue

            # If the subparser recognized the argument, add it to the parsed arguments dictionary
            parsed_arguments[name] = namespace
            break
        else:
            # The argument was not recognized by any subparser, so we add it to the list of remaining arguments
            remaining_arguments.append(argument)

    return parsed_arguments, remaining_arguments

