        # If the value is not a MappingNode, simply append it to the result
        if not isinstance(value, ruamel.yaml.nodes.MappingNode):
            result.append((key, value))
            continue

        # Find the key in the existing mapping
        for i, (existing_key, existing_value) in enumerate(result):
            if existing_key and existing_key.value == key.value:
                if isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                    # If the value is also a MappingNode, merge the two maps recursively
                    result[i] = (existing_key, deep_merge_nodes([(existing_key, existing_value), (key, value)]))
                    break
                else:
                    # Replace the existing non-MappingNode value with the new non-MappingNode value
                    result[i] = (key, value)
                    break
        else:
            # No existing key found, simply append the new key and value
            result.append((key, value))

    return result

def deep_merge_nodes(nodes):
    result = []
    for (key_node, value_node) in nodes:
        if key_node.value not in [x[0].value for x in result]:
            result.append((key_node, value_node))
        else:
            index = [x[0].value for x in result].index(key_node.value)
            result[index] = (key_node, deep_merge_node_values(
                result[index][1], value_node))
    return result


def deep_merge_node_values(node1, node2):
    if not isinstance(node1, ruamel.yaml.nodes.MappingNode):
        return node2
    if not isinstance(node2, ruamel.yaml.nodes.MappingNode):
        return node1

    result = []
    for (key_node1, value_node1) in node1.value:
        if (key_node1.value not in [x[0].value for x in node2.value] or
            not isinstance(value_node1, ruamel.yaml.nodes.MappingNode)):
            result.append((key_node1, value_node1))
        else:
            index = [x[0].value for x in node2.value].index(key_node1.value)
            result.append((key_node1, deep_merge_node_values(
                value_node1, node2.value[index][1])))
    return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=result)

def deep_merge_nodes(nodes):
    merged_nodes = []
    for key, value in nodes:
        # If the key is not a ScalarNode or the key and value are both MappingNodes, merge the values
        if not isinstance(key, ruamel.yaml.nodes.ScalarNode) or isinstance(value, ruamel.yaml.nodes.MappingNode):
            merged_value = {}
            for v_key, v_value in nodes:
                if isinstance(v_key, ruamel.yaml.nodes.ScalarNode) and v_key.value == key.value:
                    if isinstance(v_value, ruamel.yaml.nodes.MappingNode):
                        for inner_key, inner_value in v_value.value:
                            merged_value[inner_key.value] = inner_value.value
                    else:
                        merged_value[key.value] = value.value
            merged_nodes.append((key, ruamel.yaml.nodes.MappingNode(value=merged_value)))
        # Otherwise, add the node as is
        else:
            merged_nodes.append((key, value))
    return merged_nodes

def deep_merge_nodes(nodes):
    result = {}
    for node in nodes:
        key, value = node
        if key in result:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                # merge two MappingNodes
                result[key].value.extend(value.value)
            else:
                # replace the value of a key with a non-MappingNode
                result[key] = value
        else:
            result[key] = value
    return result.items()

