class ArgumentParser:
    def parse_arguments(unparsed_arguments):
        # Create a dict to store the parsed arguments
        arguments = dict()

        # Iterate through the unparsed arguments
        for argument in unparsed_arguments:
            # Check if the argument is a sub-parser argument
            if argument.startswith("--"):
                # Split the sub-parser name and the argument value
                subparser_name, argument_value = argument.split("=", 2)

                # Add the sub-parser name to the dict
                if subparser_name not in arguments:
                    arguments[subparser_name] = []

                # Add the argument value to the list for the sub-parser
                arguments[subparser_name].append(argument_value)
            else:
                # If the argument is not a sub-parser argument, store it as the global argument
                arguments["global"] = argument

        # Return the parsed arguments as a dict
        return arguments

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    from collections import defaultdict
    arguments = defaultdict(argparse.Namespace)

    for unparsed_argument in unparsed_arguments:
        try:
            argument_info = argparse.ArgumentParser(argument_default=argparse.SUPPRESS).parse_args(unparsed_argument.split())
        except SystemExit:
            continue
        if argument_info.message:
            continue
        if argument_info.func:
            arguments["global"] = argument_info
        else:
            subparser_name = argument_info.subparsers[0]
            arguments[subparser_name] = argument_info

    return dict(arguments)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    parsed_args = {}
    remaining_arguments = []

    for arg in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                subparser.add_argument(arg)
            except ArgumentError as e:
                pass
            else:
                parsed_args[subparser_name] = subparser.parse_args()
                break
        else:
            remaining_arguments.append(arg)

    return parsed_args, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            try:
                args, remaining = parser.parse_known_args([arg])
                parsed_args[name] = args
                break
            except SystemExit:
                remaining_args.append(arg)

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    subparser_names = tuple(subparsers)
    parsed_arguments = {sp_name: None for sp_name in subparser_names}
    remaining_arguments = list(unparsed_arguments)

    for sp_name, sp_parser in subparsers.items():
        while remaining_arguments:
            arg = remaining_arguments[0]
            if arg in sp_parser.supported_arguments:
                try:
                    args = sp_parser.parse_args(remaining_arguments)
                except ArgumentError as e:
                    raise ArgumentError(
                        f"Error while parsing arguments for subparser {sp_name}: {e}"
                    )
                parsed_arguments[sp_name] = args
                remaining_arguments = []
            else:
                remaining_arguments = remaining_arguments[1:]

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for arg in unparsed_arguments:
        for subparser in subparsers:
            parser = subparsers[subparser]
            # check if the argument matches any of the subparser's optional or required arguments
            match = [a for a in parser._option_string_actions if a.option_strings == arg]
            if match:
                # found a match, add the parsed arguments to the subparsed_args
                parsed_args[subparser] = parser.parse_args(unparsed_arguments[1:])
                break
        else:
            # no match, add the argument to the remaining arguments
            remaining_args.append(arg)
    return parsed_args, remaining_args

