    current_index = 0
    max_index = len(response)
    while current_index < max_index:
        yield response[current_index:current_index+max_results]
        current_index += max_results

    if current_index < max_index:
        yield response[current_index:max_index]

def size_to_bytes(size: str) -> int:
    """
    Convert human-readable file size to bytes.

    :param size: A string representing a human-readable file size (e.g. '500K')
    :return: A decimal representation of file size
    """
    size = size.strip()
    unit_mapping = {'K': 1024, 'M': 1024*1024, 'G': 1024*1024*1024, 'T': 1024*1024*1024*1024}
    try:
        num, unit = size.split()
        num = float(num)
        multiplier = unit_mapping[unit[0]]
        return int(round(num * multiplier))
    except:
        raise ValueError(f"Invalid input size: '{size}'. Must be in the format 'N[K|M|G|T]'")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples:

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('KB'):
        return int(float(size.replace('KB', '')) * 1000)
    elif size.endswith('MB'):
        return int(float(size.replace('MB', '')) * 1000000)
    elif size.endswith('GB'):
        return int(float(size.replace('GB', '')) * 1000000000)
    else:
        return int(size)

