def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")
    if not all(isinstance(char, str) for char in alphabet):
        raise ValueError("alphabet must contain only strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer or None")

    if number == 0:
        return alphabet[0]

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        while len(digits) < padding:
            digits.insert(0, alphabet[0])

    return "".join(reversed(digits))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two elements")
    if padding is not None and len(alphabet) < 2**padding:
        raise ValueError("alphabet must contain at least 2^padding elements")

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = "0" * (padding - len(result)) + result

    return result

