def hist_to_graph(hist, make_value=None, get_coordinate="left",
                              field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph."""
    # Check the input parameters
    if not isinstance(hist, Histogram):
        raise ValueError("hist must be a Histogram object")
    if not callable(make_value) and make_value is not None:
        raise ValueError("make_value must be a function or None")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != 2:
        raise ValueError("field_names must be a tuple of length 2")
    if scale is not None and not isinstance(scale, GraphScale):
        raise ValueError("scale must be a GraphScale object or None")

    # Create the graph
    graph = Graph(field_names=field_names, scale=scale)

    # Loop through the histogram bins
    for bin_ in hist:
        # Determine the coordinate of the bin
        if get_coordinate == "left":
            x, y = bin_.left, bin_.hits
        elif get_coordinate == "right":
            x, y = bin_.right, bin_.hits
        else:
            x, y = (bin_.left + bin_.right) / 2, bin_.hits

        # Add the bin to the graph
        graph.add_point((x, y), make_value=make_value)

    return graph

