    missing_attributes = set(attributes) - set(candidate.__dict__.keys())
    if missing_attributes:
        raise zope.interface.Invalid("The candidate is missing required attributes: {}".format(", ".join(missing_attributes)))

    # Check the signatures of the methods and attributes
