        raise ValueError("Cannot convert non-timezone-aware datetime")
    except AttributeError:
        # The provided datetime does not have a 'fold' attribute.
        raise ValueError("Cannot convert datetime with no 'fold' attribute")
    except RuntimeError:
        # The provided datetime is in an invalid or ambiguous state.
        raise ValueError("Cannot convert invalid or ambiguous datetime")

