            elif arg == "False" or arg == "false":
                return False
            else:
                raise ValueError(f"Invalid boolean value: {arg}")
        # Convert integer values
        elif arg_type == int:
            try:
                return int(arg)
            except ValueError:
                raise ValueError(f"Invalid integer value: {arg}")
        # Convert float values
        elif arg_type == float:
            try:
                return float(arg)
            except ValueError:
                raise ValueError(f"Invalid float value: {arg}")
        # Convert string values (default)
        else:
            return arg

    # Convert each argument in the values_dict
    for arg, arg_value in values_dict.items():
        # Validate input type
        if not isinstance(arg_value, str):
            raise ValueError(f"Invalid input type for argument {arg}: expected str, got {type(arg_value)}")
        # Convert value to correct type
        arg_type = parser_name.arg_types["arguments"].get(arg)
        if arg_type is not None:
            values_dict[arg] = convert_arg(arg_value, arg_type)
        else:
            # If no type is specified, leave the value as a string
            pass

    return values_dict

